const text = $input.first().json.output.replace(/\\n/g, '\n');
const parts = text.split(/(?=\/coder|\/review)/g).filter(p => p.trim());

return parts.map(part => ({
  json: {
    tag: part.match(/^\/(coder|review)/)?.[1] || 'unknown',
    content: part.replace(/^\/(coder|review)\s*/, '').trim()
  }
}));

// Берём retryCount из входа ПРАВЕР ТЕГОВ, а не из его выхода
const previousRetry = $('В зависимости от тега передаем').first().json.retryCount || 0;
const retryCount = previousRetry + 1;

const text = ($input.first().json.output || '').replace(/\\n/g, '\n');

// Если больше 3 попыток — ошибка
if (retryCount > 2) {
  return [{
    json: {
      tag: 'error',
      content: 'Ошибка: не удалось разметить задачи тегами после 3 попыток. Попробуйте переформулировать задачу.\n\nИсходный текст:\n' + text,
      retryCount: retryCount
    }
  }];
}

const parts = text.split(/(?=\/coder|\/review)/g).filter(p => p.trim());

const results = parts
  .map(part => ({
    json: {
      tag: part.match(/^\/(coder|review)/)?.[1] || 'unknown',
      content: part.replace(/^\/(coder|review)\s*/, '').trim(),
      retryCount: retryCount
    }
  }))
  .filter(item => item.json.tag !== 'unknown');

if (results.length === 0) {
  return [{
    json: {
      tag: 'unknown',
      content: text,
      retryCount: retryCount
    }
  }];
}

return results;

const combined = {};

for (const item of $input.all()) {
  for (const [key, value] of Object.entries(item.json)) {
    if (value !== null && value !== undefined && value !== '') {
      combined[key] = value;
    }
  }
}

return [{ json: combined }];
